export const LESSONS={
 doors:{title:'Una puerta no completa el cierre',group:'doors',objective:'Relacionar una obstrucción con un cierre incompleto y comprobar el ciclo después de retirarla.',symptom:'El mando solicita cerrar, pero una hoja no llega a su posición final.',observe:'Enfoca las hojas y observa la marca naranja en el recorrido. Después pulsa Revisar para obtener la evidencia.',evidence:[['Mando de cierre','Recibido'],['Recorrido de la hoja','Obstáculo virtual detectado'],['Confirmación de cierre','No disponible']],diagnosis:[{id:'motor',label:'Fallo del motor de tracción',why:'La tracción no explica un objeto en el recorrido de la puerta. Revisa la evidencia de obstrucción.'},{id:'obstacle',label:'Obstáculo en el recorrido de la hoja',correct:true,why:'La orden llega, pero el objeto impide completar el recorrido.'},{id:'lighting',label:'Fallo de iluminación',why:'La iluminación no determina la posición final de la hoja en este ejercicio.'}],repairs:[{id:'remove',label:'Retirar el obstáculo virtual',correct:true,why:'Elimina la causa observada y permite ensayar el recorrido completo.'},{id:'override',label:'Ignorar la confirmación de cierre',why:'Ocultar el aviso no elimina el obstáculo. Debes corregir la causa y comprobar el ciclo.'},{id:'replace',label:'Sustituir el bogie',why:'El bogie no interviene en el obstáculo de esta puerta.'}],test:'Se representa un ciclo de apertura y cierre. Comprueba que el recorrido queda libre y que aparece la confirmación de cierre.',results:[['Recorrido','Libre'],['Ciclo de apertura/cierre','Completado'],['Confirmación de cierre','Recibida']],reflection:[{id:'order',label:'La orden de cierre recibida basta para dar el tren por listo.',why:'La orden y la confirmación son señales diferentes: debe comprobarse que la puerta llegó al cierre.'},{id:'confirm',label:'Hay que comprobar el recorrido y la confirmación de cierre.',correct:true,why:'La comprobación final demuestra que la intervención resolvió el síntoma.'}]},
 ventilation:{title:'La ventilación no responde',group:'roof',objective:'Distinguir un mando recibido de la disponibilidad de alimentación auxiliar en un circuito simulado.',symptom:'Se solicita ventilación, pero el ventilador del ejercicio permanece detenido.',observe:'Enfoca la cubierta y los equipos asociados. Revisa el estado del circuito auxiliar en el esquema.',evidence:[['Mando de ventilación','Recibido'],['Interruptor auxiliar simulado','Desconectado'],['Respuesta del equipo','Sin giro / sin flujo']],diagnosis:[{id:'blade',label:'Daño confirmado en las aspas',why:'No se ha observado daño en las aspas. La evidencia señala un interruptor desconectado.'},{id:'auxiliary',label:'Alimentación auxiliar interrumpida',correct:true,why:'El mando llega, pero el circuito simulado no suministra energía al equipo.'},{id:'door',label:'Obstáculo en una puerta',why:'Las evidencias corresponden al circuito de ventilación, no a las puertas.'}],repairs:[{id:'body',label:'Sustituir un panel de carrocería',why:'Cambiar la carrocería no restablece el circuito auxiliar.'},{id:'restore',label:'Restablecer el interruptor auxiliar virtual',correct:true,why:'Restablece la causa identificada. La alimentación sólo se habilita durante el ensayo simulado.'},{id:'ignore',label:'Marcar el ventilador como correcto sin probarlo',why:'Todavía no se ha demostrado que el equipo responda.'}],test:'El esquema habilita la alimentación de ensayo y muestra el giro. Comprueba mando, circuito y respuesta.',results:[['Circuito auxiliar de ensayo','Disponible'],['Giro del ventilador','Representado'],['Respuesta de ventilación','Correcta en el ejercicio']],reflection:[{id:'command',label:'Recibir el mando garantiza que el equipo está funcionando.',why:'El mando recibido no confirma alimentación ni respuesta del equipo.'},{id:'response',label:'Deben comprobarse el mando, la alimentación y la respuesta.',correct:true,why:'Las tres evidencias permiten distinguir una orden de un funcionamiento comprobado.'}]},
 running:{title:'Marca de desgaste en rodadura',group:'mechanics',objective:'Localizar una anomalía de rodadura y distinguir inspección visual, intervención y prueba funcional.',symptom:'Una rueda del ejercicio presenta una zona marcada como desgaste irregular.',observe:'Enfoca Rodaje y bajos. La marca naranja identifica una anomalía virtual; no es una medición de desgaste del tren real.',evidence:[['Zona señalada','Rodadura'],['Inspección visual simulada','Desgaste irregular'],['Conjunto seleccionado','Rueda del ejercicio']],diagnosis:[{id:'wheel',label:'Anomalía en la rodadura señalada',correct:true,why:'La evidencia visual está localizada en la rueda.'},{id:'vent',label:'Interrupción de la ventilación',why:'No hay una evidencia de ventilación en esta incidencia.'},{id:'window',label:'Fallo de una ventana',why:'La zona señalada pertenece al rodaje, no a las ventanas.'}],repairs:[{id:'paint',label:'Ocultar la marca con pintura virtual',why:'Ocultar la indicación no representa una corrección de la anomalía.'},{id:'wheel',label:'Sustituir la rueda virtual del ejercicio',correct:true,why:'La sustitución representa la intervención en la pieza identificada; no se reproducen procedimientos de desmontaje reales.'},{id:'door',label:'Ajustar una puerta',why:'La puerta no explica la evidencia de rodadura.'}],test:'El esquema representa el giro de la rueda intervenida. Confirma la retirada de la incidencia y el resultado del ensayo.',results:[['Pieza virtual','Sustituida'],['Incidencia del ejercicio','Retirada'],['Giro representado','Sin anomalía simulada']],reflection:[{id:'visual',label:'El ensayo visual certifica el bogie real.',why:'Esta práctica no mide tolerancias, esfuerzos ni criterios de aceptación del fabricante.'},{id:'scope',label:'El ensayo confirma el ejercicio; una revisión real requiere criterios del fabricante.',correct:true,why:'El resultado didáctico no sustituye mediciones ni documentación específica del modelo.'}]}
};
export const STAGES=['Preparar','Observar','Diagnosticar','Intervenir','Comprobar','Explicar'];
export class GuidedMaintenance{
 constructor(){this.reset('doors');}
 reset(id){if(!LESSONS[id])throw Error('Práctica no disponible.');Object.assign(this,{id,stage:0,isolated:false,inspected:false,diagnosed:false,repaired:false,passed:false,completed:false,testing:false,attempts:0,log:[]});}
 expect(stage){if(this.testing)throw Error('Espera a que termine el ensayo.');if(this.stage!==stage)throw Error('Completa el paso actual antes de continuar.');}
 isolate(){this.expect(0);this.isolated=true;this.stage=1;this.log.push('Preparación: equipo aislado en el ejercicio.');return 'Preparación completada. Localiza el conjunto y revisa la evidencia.';}
 inspect(group){this.expect(1);if(group!==LESSONS[this.id].group)throw Error('Localiza '+({doors:'Puertas de pasajeros',roof:'Cubierta y ventilación',mechanics:'Rodaje y bajos'}[LESSONS[this.id].group])+' con el botón Enfocar la pieza antes de revisar.');this.inspected=true;this.stage=2;this.log.push('Observación: '+LESSONS[this.id].evidence.map(x=>x.join(': ')).join(' · '));return 'Evidencias obtenidas. Elige la causa que las explica.';}
 choose(kind,id){const stages={diagnosis:2,repairs:3,reflection:5};this.expect(stages[kind]);const option=LESSONS[this.id][kind]?.find(x=>x.id===id);if(!option)throw Error('Selecciona una opción disponible.');if(!option.correct){this.attempts++;return {correct:false,message:option.why};}this.stage++;if(kind==='diagnosis')this.diagnosed=true;if(kind==='repairs')this.repaired=true;if(kind==='reflection')this.completed=true;this.log.push(option.label+' '+option.why);return {correct:true,message:option.why};}
 beginTest(){this.expect(4);this.testing=true;this.log.push('Ensayo iniciado: resultado pendiente.');return 'Ensayo en curso. Observa el esquema durante 3 segundos.';}
 finishTest(){if(!this.testing||this.stage!==4)return false;this.testing=false;this.passed=true;this.stage=5;this.log.push('Ensayo terminado: '+LESSONS[this.id].results.map(x=>x.join(': ')).join(' · '));return true;}
 cancelTest(){if(this.testing){this.testing=false;this.log.push('Ensayo interrumpido; repítelo antes de continuar.');}}
}
